def stable_toposort(graph):
    if not graph:
        return []

    nodes = list(graph.keys())
    node_set = set(nodes)

    # Check for missing dependencies
    for node, deps in graph.items():
        for dep in deps:
            if dep not in node_set:
                raise ValueError(f"Missing dependency: {dep} required by {node}")

    # Build indegree and dependents
    indegree = {node: 0 for node in nodes}
    dependents = {node: [] for node in nodes}

    for node, deps in graph.items():
        seen = set()
        for dep in deps:
            if dep not in seen:
                seen.add(dep)
                indegree[node] += 1
                dependents[dep].append(node)

    result = []
    processed = set()

    while len(result) < len(nodes):
        chosen = None
        # Find first node in original order with indegree 0
        for node in nodes:
            if node not in processed and indegree[node] == 0:
                chosen = node
                break

        if chosen is None:
            raise ValueError("Cycle detected in graph")

        result.append(chosen)
        processed.add(chosen)

        for dependent in dependents[chosen]:
            indegree[dependent] -= 1

    return result
```

