def schema_drift(expected, actual):
    result = []

    def collect_leaves(node, path, res):
        if isinstance(node, dict):
            for k, v in node.items():
                child = f"{path}.{k}" if path else k
                collect_leaves(v, child, res)
        else:
            if path:
                res.append(path)

    def compare(e, a, path):
        if isinstance(e, dict) and isinstance(a, dict):
            for key in set(e.keys()) | set(a.keys()):
                child = f"{path}.{key}" if path else key
                if key not in e:
                    collect_leaves(a[key], child, result)
                elif key not in a:
                    collect_leaves(e[key], child, result)
                else:
                    compare(e[key], a[key], child)
        elif isinstance(e, dict) != isinstance(a, dict):
            if path:
                result.append(path)
        else:
            if e != a:
                if path:
                    result.append(path)

    compare(expected, actual, '')
    return sorted(result)
